const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || args.instruction || '').trim();
const messageId = String(source.messageId || source.id || args.messageId || args.id || payload.messageId || payload.id || '').trim();
const query = String(source.query || args.query || payload.query || rawText).trim();
const sender = String(source.sender || args.sender || payload.sender || '').trim();
const subject = String(source.subject || args.subject || payload.subject || '').trim();
const hasTarget = Boolean(messageId || query || sender || subject);
return [{ json: { ...source, payload, message, chatId, rawText, messageId, query, sender, subject, hasTarget, response: hasTarget ? '' : 'Mia cần ít nhất messageId, query, sender hoặc subject để lưu trữ mail.' } }];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.messageId || item.threadId);
if (!rows.length) {
  return [{ json: { ...source, ok: false, response: 'Mia chưa tìm thấy email phù hợp để lưu trữ.' } }];
}
const item = rows[0];
return [{ json: { ...source, ok: true, messageId: item.id || item.messageId || '', emailSubject: item.subject || source.subject || '', emailFrom: item.from || '', emailSnippet: item.snippet || '' } }];

const source = $('Prepare Action').item.json || {};
const result = $json || {};
const title = source.subject || result.emailSubject || source.query || source.sender || source.messageId || 'email';
let text = `Đã lưu trữ email: ${title}`;
if (source.messageId || result.messageId || result.id) text += `\nMessage ID: ${source.messageId || result.messageId || result.id}`;
if (source.sender || result.emailFrom) text += `\nNgười gửi: ${source.sender || result.emailFrom}`;
return [{ json: { chatId: source.chatId || '', text: text.trim(), messageId: source.messageId || result.messageId || result.id || '' } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target = source.subject || source.sender || source.query || source.messageId || source.id || '';
let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
